好。不过我这边没有你以前写过的代码，不知道你说的“我的风格”具体是：

- 数组还是 `vector`
- 递归还是迭代
- 要不要注释
- 用不用 `#define int long long` 之类的宏

先按最常见的 C++ 竞赛风格给你一版，逻辑是对的。你发一段你平时写的代码，我可以马上照着你的模板改。

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> m(n + 1);
    vector<int> p(n + 1);
    vector<vector<int>> child(n + 1);
    vector<int> remain(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        cin >> m[i] >> p[i];
        if (p[i] != 0) {
            child[p[i]].push_back(i);
            ++remain[p[i]];
        }
    }

    vector<long long> w = m;          // w[v]：子树 v 的总字母数
    vector<long long> dp(n + 1, 0);   // dp[v]：子树 v 内部的最小代价

    queue<int> q;
    for (int i = 1; i <= n; ++i) {
        if (remain[i] == 0) q.push(i);
    }

    long long ans = 0;

    while (!q.empty()) {
        int v = q.front();
        q.pop();

        // 儿子按子树总字母数从大到小
        sort(child[v].begin(), child[v].end(), [&](int a, int b) {
            return w[a] > w[b];
        });

        for (int i = 0; i < (int)child[v].size(); ++i) {
            int u = child[v][i];
            dp[v] += dp[u] + 1LL * i * w[u];
        }

        if (p[v] == 0) {
            ans += dp[v];
        } else {
            w[p[v]] += w[v];
            if (--remain[p[v]] == 0) {
                q.push(p[v]);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}
```

关键就三行：

```cpp
sort(child[v].begin(), child[v].end(), [&](int a, int b) {
    return w[a] > w[b];
});

dp[v] += dp[u] + 1LL * i * w[u];
```

其中 `i` 是这个儿子块前面有几个兄弟块。

复杂度：

\[
O(n\log n)
\]

用队列从叶子往根算，不会递归爆栈。

如果答案可能超过 `long long`，`dp` 和 `ans` 要换成 `__int128`。

#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[222222];
int f[222222],d[222222],vis[222222],di[222222];
int dp[555555][22];
void dfs(int p,int g,int fa){
	d[p]=g;
	dp[p][0]=fa;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return d[x];
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i];
			y=dp[y][i];
		}
	} 
	return d[dp[x][0]];
}
int dis(int x,int y){
	return d[x]+d[y]-2*lca(x,y);
} 
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,k,qq;
	cin>>n>>k>>qq;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1,1,0);
	queue<int>q;
	for(int i=1;i<=k;i++){
		int x;
		cin>>x;
		vis[x]=1;
		q.push(x);
	}
	while(!q.empty()){
		int x=q.front();
		q.pop();
		for(int i=0;i<v[x].size();i++){
			if(vis[v[x][i]]==0){
				q.push(v[x][i]);
				vis[v[x][i]]=1;
				di[v[x][i]]=di[x]+1;
			}
		}
	}
	while(qq--){
		int x,y;
		cin>>x>>y;
		if(k==0){
			cout<<dis(x,y)<<endl;
			continue;
		}
		cout<<min(dis(x,y),di[x]+di[y])<<endl;
	}
    return 0;
}

按你这份代码的风格写的：`#define int long long`、全局数组、`signed main`、快读、1-index。

这里用队列从叶子往上算，不用递归，链状树也不会爆栈。

```cpp
#include<bits/stdc++.h>
#define int long long
using namespace std;
const int N=222222;
vector<int>e[N];
int a[N],fa[N],sum[N],dp[N],deg[N],ans;
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i]>>fa[i];
		if(fa[i]){
			e[fa[i]].push_back(i);
			deg[fa[i]]++;
		}
	}
	queue<int>q;
	for(int i=1;i<=n;i++){
		sum[i]=a[i];
		if(deg[i]==0){
			q.push(i);
		}
	}
	while(!q.empty()){
		int x=q.front();
		q.pop();
		sort(e[x].begin(),e[x].end(),[&](int u,int v){
			return sum[u]>sum[v];
		});
		for(int i=0;i<e[x].size();i++){
			int y=e[x][i];
			dp[x]+=dp[y]+i*sum[y];
		}
		if(fa[x]){
			sum[fa[x]]+=sum[x];
			if(--deg[fa[x]]==0){
				q.push(fa[x]);
			}
		}else{
			ans+=dp[x];
		}
	}
	cout<<ans<<endl;
	return 0;
}
```

关键变量：

- `sum[x]`：子树 `x` 的总字母数
- `dp[x]`：子树 `x` 内部的最小代价
- `i`：当前儿子块前面有几个兄弟块，从 0 开始
- `deg[x]`：`x` 还有几个儿子没处理

如果 `n` 超过 `222222`，把 `N` 改大。

