using namespace std;
vector<int>e[1111111];
int a[1111111],f[1111111],w[1111111],dp[1111111],d[1111111],r;
bool cmp(int x,int y){
	return w[x]>w[y];
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i]>>f[i];
		if(f[i]){
			e[f[i]].push_back(i);
			d[f[i]]++;
		}
	}
	queue<int>q;
	for(int i=1;i<=n;i++){
		w[i]=a[i];
		if(d[i]==0){
			q.push(i);
		}
	}
	while(!q.empty()){
		int x=q.front();
		q.pop();
		sort(e[x].begin(),e[x].end(),cmp);
		for(int i=0;i<e[x].size();i++){
			int y=e[x][i];
			dp[x]+=dp[y]+i*w[y];
		}
